export type ThemeColour = { hex: number; string: string; };

export interface IOperatorTheme {
    fontName: string;
    darkAccent: ThemeColour;
    midAccent: ThemeColour & { highlight: ThemeColour; };
    lightAccent: ThemeColour;
    veryLightAccent: ThemeColour;
    icons?: {
        gigIconGradient?: {
            start: string;
            end: string;
        };
    },
    textColour?: {
        heading: ThemeColour;
        body: ThemeColour;
        link: {
            default: ThemeColour;
            visited: ThemeColour;
            hover: ThemeColour;
            active: ThemeColour;
        };
    },
    primaryButton?: {
        backgroundColour: ThemeColour;
        textColour: ThemeColour;
        boxShadowColour: ThemeColour;
        outlineColour: ThemeColour;
    },
    secondaryButton?: {
        backgroundColour: ThemeColour;
        textColour: ThemeColour;
        boxShadowColour: ThemeColour;
        outlineColour: ThemeColour;
    },
    tertiaryButton?: {
        backgroundColour: ThemeColour;
        textColour: ThemeColour;
        boxShadowColour: ThemeColour;
        outlineColour: ThemeColour;
    },
    crossButton?: {
        boxShadowColour: ThemeColour;
        outlineColour: ThemeColour;
    }
}
